import socket, struct
def q(name, server="127.0.0.11", use_tcp=False):
    hdr=struct.pack(">HHHHHH", 0x1234, 0x0100, 1,0,0,0)
    qname=b"".join(bytes([len(l)])+l.encode() for l in name.split("."))+b"\x00"
    pkt=hdr+qname+struct.pack(">HH",1,1)
    if use_tcp:
        s=socket.create_connection((server,53),2); s.settimeout(2)
        s.sendall(struct.pack(">H",len(pkt))+pkt)
        ln=struct.unpack(">H",s.recv(2))[0]
        data=s.recv(ln); s.close()
    else:
        s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
        s.sendto(pkt,(server,53)); data,_=s.recvfrom(512); s.close()
    rcode=data[3]&0xF; an=struct.unpack(">H",data[6:8])[0]
    return rcode, an, data
